const message = ($json.chatInput || "").toLowerCase();

const availablePreferences = [
  "action",
  "comedy",
  "drama",
  "sci-fi",
  "science fiction",
  "romance",
  "thriller",
  "adventure",
  "animation",
  "fantasy"
];

const preferences = [];

for (const preference of availablePreferences) {
  if (message.includes(preference)) {
    if (preference === "science fiction") {
      if (!preferences.includes("sci-fi")) {
        preferences.push("sci-fi");
      }
    } else {
      preferences.push(preference);
    }
  }
}

return {
  userInput: message,
  preferences: preferences
};

const recommendations = $json.recommendations || [];

const sortedRecommendations = recommendations
  .filter(item => item.score > 0)
  .sort((a, b) => b.score - a.score);

const topRecommendations = sortedRecommendations.slice(0, 3);

return {
  userInput: $json.userInput,
  preferences: $json.preferences,
  recommendations: topRecommendations
};

const preferences = $json.preferences || [];

const movies = [
  {
    title: "Interstellar",
    genres: ["sci-fi", "drama", "adventure"]
  },
  {
    title: "The Dark Knight",
    genres: ["action", "drama", "thriller"]
  },
  {
    title: "Avengers: Endgame",
    genres: ["action", "adventure", "sci-fi"]
  },
  {
    title: "The Hangover",
    genres: ["comedy"]
  },
  {
    title: "The Notebook",
    genres: ["romance", "drama"]
  },
  {
    title: "Inception",
    genres: ["sci-fi", "thriller", "action"]
  },
  {
    title: "Toy Story",
    genres: ["animation", "comedy", "adventure"]
  },
  {
    title: "The Lord of the Rings",
    genres: ["fantasy", "adventure", "drama"]
  },
  {
    title: "Joker",
    genres: ["drama", "thriller"]
  },
  {
    title: "Spider-Man",
    genres: ["action", "adventure", "sci-fi"]
  }
];

const recommendations = movies.map(movie => {
  const matchedPreferences = movie.genres.filter(genre =>
    preferences.includes(genre)
  );

  const score = matchedPreferences.length;

  return {
    title: movie.title,
    genres: movie.genres,
    matchedPreferences,
    score
  };
});

return {
  userInput: $json.userInput,
  preferences,
  recommendations
};

