(() => {
  const recommendations = $json.recommendations || [];
  const preferences = $json.preferences || [];

  if (preferences.length === 0) {
    return "I couldn't identify any supported preferences. Try action, comedy, drama, sci-fi, romance, thriller, adventure, animation, or fantasy.";
  }

  if (recommendations.length === 0) {
    return `You selected: ${preferences.join(", ")}.\n\nI couldn't find a matching recommendation.`;
  }

  let response = `Based on your preferences (${preferences.join(", ")}), here are your top recommendations:\n\n`;

  recommendations.forEach((movie, index) => {
    response += `${index + 1}. ${movie.title}\n`;
    response += `Genres: ${movie.genres.join(", ")}\n`;
    response += `Matched preferences: ${movie.matchedPreferences.join(", ")}\n`;
    response += `Match score: ${movie.score}\n\n`;
  });

  return response;
})()
}}
